&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;We always aim to stick to the above process, however there may be occasions when an&amp;nbsp;additional&amp;nbsp;interview stage is needed for us to be sure&amp;nbsp;we’re&amp;nbsp;hiring the right&amp;nbsp;fit for the role.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;HIRING LOCATIONS📍&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;Here are the locations that we are looking to hire from for this role. Please note, we are not looking to engage with candidates outside of these locations.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;UK&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;All new team members start their first day in our office to collect the equipment needed to work remotely.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;ABOUT FORM3&amp;nbsp;💭&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;Revolutionising the world of payments with our cloud-native, multi-cloud platform. For more information about Form3, check out the following pages:&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;a href=&quot;https://www.form3.tech/platform&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;What we do&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;|&amp;nbsp;&lt;/span&gt;&lt;a href=&quot;https://www.form3.tech/culture&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;Life at Form3&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;|&amp;nbsp;&lt;/span&gt;&lt;a href=&quot;https://www.youtube.com/@Form3Cloud/podcasts&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;P&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;ayments Cannot&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;Fail&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;Series&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;|&amp;nbsp;&lt;/span&gt;&lt;a href=&quot;https://techpodcast.form3.tech/episodes&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;.Tech&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;&amp;nbsp;Podcast&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:1,&amp;quot;335551620&amp;quot;:1,&amp;quot;335559685&amp;quot;:0,&amp;quot;335559737&amp;quot;:0,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;OUR DEI&amp;amp;B COMMITMENT&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:259}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;We hire talented people from a variety of backgrounds and experiences and are committed to a work environment based on diversity, open-mindedness and curiosity. We’re united by our company values (we even created them together!) and we celebrate our unique differences.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:259}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;Our employee lifecycle processes are designed to embrace equal opportunity and prevent discrimination against our people regardless of personal characteristics. It is our strong belief that the more inclusive and belonging we are as a business, the better our work will be.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:259}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;As an inclusive employer, we guarantee to interview all neurodiverse and physically disabled applicants who meet the minimum criteria for this role. We also encourage candidates to notify us of any reasonable adjustments that may be required during the recruitment process. This includes providing job adverts in alternative, accessible formats or adjustments required at interview stage.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:259}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;If you consider yourself to be neurodiverse or physically disabled under the UN definition of disability and would like to be considered under this scheme and/or require any reasonable adjustments please let us know by sending an email to &lt;/span&gt;&lt;a ----- ----- data-contrast=&quot;none&quot;&gt; clearly stating your consent for us to process this data. &lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;For more information please refer to our &lt;/span&gt;&lt;a href=&quot;https://www.form3.tech/legal/recruitment-data-policy&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Recruitment Data Policy&lt;/span&gt;&lt;/a&gt;&lt;span data-contrast=&quot;none&quot;&gt;.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:259}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;&lt;/div&gt;<p>Find more <a href="https://www.arbeitnow.co.uk/english-speaking-jobs">English Speaking Jobs in United Kingdom</a> on Arbeitnow</a>

&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;From Fivetran’s founding until now, our mission has remained the same: to make access to data as simple and reliable as electricity. With Fivetran, customer data arrives in their warehouses, canonical and ready to query, with no engineering or maintenance required. We’re proud that more organizations continue to leverage our technology every day to become truly data-driven.&lt;/p&gt;&lt;/div&gt;&lt;p&gt;&lt;b&gt;About Us&lt;/b&gt;&lt;br&gt;Fivetran and dbt Labs are bringing together two industry-leading companies with a shared mission: helping organizations unlock the full value of their data.&lt;br&gt;&lt;br&gt;Together, we’re delivering the data infrastructure layer that helps organizations move, transform, and trust their data — from the moment data moves, through every transformation, to the context teams and AI systems rely on.&lt;br&gt;&lt;br&gt;Fivetran helps organizations automate data movement across the systems, clouds, engines, and tools they rely on. dbt Labs pioneered analytics engineering, helping teams transform data into reliable, governed insights. Together, we support thousands of organizations as they build a trusted foundation for analytics, AI, and better business decisions.&lt;br&gt;&lt;br&gt;As we bring our teams and technology together, we’re building on the strengths of both companies while continuing to deliver the products and experiences our customers know and trust. It’s an exciting time to join us: we’re creating a company with the scale, talent, and technology to help more organizations put their data to work with greater speed, confidence, and impact.&lt;br&gt;&lt;br&gt;During this transition period, you may see references to both Fivetran and dbt Labs throughout our recruiting process as we integrate our teams, systems, and career sites.&lt;/p&gt;&lt;h1&gt;&lt;/h1&gt;&lt;h2&gt;&lt;b&gt;About the Role&lt;/b&gt;&lt;/h2&gt;&lt;p&gt;We&#39;re hiring a Senior Manager to lead our Partner Solutions Architecture (Partner SA) team across EMEA and APJ.&lt;/p&gt;&lt;br&gt;&lt;p&gt;The team owns the technical relationship with systems integrators, consultancies and technology partners across these regions, and works alongside our alliances team as the regional route to market for our global platform partners.&lt;/p&gt;&lt;br&gt;&lt;p&gt;This is a people leadership role, but you&#39;ll need enough technical experience to coach the team and get hands-on when it&#39;s needed. You&#39;ll be working across two theatres and several time zones. When a partner relationship needs senior involvement, you&#39;ll step in alongside the Partner SA who owns it.&lt;/p&gt;&lt;br&gt;&lt;p&gt;This role drives revenue via partners by championing partner technical capability and engagement with Fivetran and dbt. With the team, you will scale partner technical cosell and champion our partners&#39; ability to communicate the value of Fivetran and the dbt platform, identify the right use cases, design best-practice architectures and deliver high-quality implementations. &lt;/p&gt;&lt;br&gt;&lt;p&gt;You&#39;ll report to the Global Head of Partner Solutions Architecture and work closely with your counterpart who leads the AMER team. Outside the Partner SA team, you&#39;ll work most closely with the regional partner leaders for EMEA and APJ and their partner sales and partner development managers, as well as field engineering leadership in both theatres.&lt;/p&gt;&lt;br&gt;&lt;h2&gt;What You’ll Do&lt;/h2&gt;&lt;ul&gt;&lt;li style=&quot;color:#000000 !important&quot;&gt;Own regional success jointly with your partner leadership counterparts, and be able to explain what&#39;s driving performance.&lt;/li&gt;&lt;li style=&quot;color:#000000 !important&quot;&gt;Own capability outcomes for the region, including certification and accreditation growth, local enablement program strategy and partner reach, and put a scalable, consistent operating rhythm in place.&lt;/li&gt;&lt;li style=&quot;color:#000000 !important&quot;&gt;Turn global alliance strategy into regional execution, working with the platform partners&#39; local field teams and the SIs delivering on those platforms.&lt;/li&gt;&lt;li&gt;Lead, coach and develop the EMEA and APJ Partner SA team, including regular 1:1s, clear expectations, performance conversations and career development&lt;/li&gt;&lt;li style=&quot;color:#000000 !important&quot;&gt;Own the coverage model for both geos, including who covers which partners and territories, where we need more support, and how we prioritise &lt;/li&gt;&lt;li style=&quot;color:#000000 !important&quot;&gt;Build and retain a high-performing team, including hiring as the team grows.&lt;/li&gt;&lt;li style=&quot;color:#000000 !important&quot;&gt;Share what you&#39;re seeing in the region with the global product Partner SAs and the product team, such as integration gaps, recurring delivery issues, competitive dynamics and roadmap requests, backed up with data where possible.&lt;/li&gt;&lt;li style=&quot;color:#000000 !important&quot;&gt;Travel approximately 30% across both theatres for partner planning, enablement delivery, regional events and time with your team.&lt;/li&gt;&lt;/ul&gt;&lt;br&gt;&lt;h2&gt;Skills We’re Looking For&lt;/h2&gt;&lt;ul&gt;&lt;li style=&quot;color:#000000 !important&quot;&gt;Experience managing a distributed customer- or partner-facing technical team (e.g. solutions architecture, sales engineering, partner engineering or consulting delivery), including hiring, performance management and developing people.&lt;/li&gt;&lt;li style=&quot;color:#000000 !important&quot;&gt;A background in partner, alliance or channel motions, with a good understanding of how SIs and technology partners make money and set priorities.&lt;/li&gt;&lt;li style=&quot;color:#000000 !important&quot;&gt;A solid understanding of the modern data stack (ingestion, transformation, orchestration, warehouses and lakehouses, open table formats, semantic layers, catalogs and BI) and how it all fits together.&lt;/li&gt;&lt;li style=&quot;color:#000000 !important&quot;&gt;A track record of building capability in partner or customer organisations, for example through enablement programs, certification or accreditation paths, workshops and labs, or helping partners build a practice.&lt;/li&gt;&lt;li style=&quot;color:#000000 !important&quot;&gt;Comfortable in commercial conversations, including regional pipeline reviews, partner business planning and being accountable for a number.&lt;/li&gt;&lt;/ul&gt;&lt;p&gt;&lt;br&gt;&lt;br&gt;&lt;/p&gt;&lt;h2&gt;Bonus Skills​&lt;/h2&gt;&lt;ul&gt;&lt;li style=&quot;color:#000000 !important&quot;&gt;Hands-on experience with dbt and with Fivetran.&lt;/li&gt;&lt;li&gt;Experience leading a team through organisational change&lt;/li&gt;&lt;li style=&quot;color:#000000 !important&quot;&gt;Experience running partner certification, accreditation or enablement programs.&lt;/li&gt;&lt;li style=&quot;color:#000000 !important&quot;&gt;Established relationships in the EMEA or APJ partner ecosystem.&lt;/li&gt;&lt;li style=&quot;color:#000000 !important&quot;&gt;Familiarity with cloud marketplace motions and co-sell programs.&lt;/li&gt;&lt;/ul&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p class=&quot;p-rich_text_section&quot; style=&quot;line-height: 1.3;&quot;&gt;&lt;strong data-stringify-type=&quot;bold&quot;&gt;Perks and Benefits&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;100% employer-paid medical insurance&lt;strong&gt;*&lt;/strong&gt;&lt;/li&gt;
&lt;li data-pm-slice=&quot;1 1 []&quot;&gt;Generous paid time away from work, including paid vacation or flexible/unlimited vacation depending on role and country, plus paid sick time, inclusive parental leave, paid holidays, including a year-end Global Week of Rest, and volunteer days off.&lt;/li&gt;
&lt;li&gt;RSU stock grants*&lt;/li&gt;
&lt;li&gt;Professional development and training opportunities&lt;/li&gt;
&lt;li&gt;Company virtual happy hours, free food, and fun team-building activities&lt;/li&gt;
&lt;li&gt;Monthly cell phone stipend&lt;/li&gt;
&lt;li&gt;Access to an innovative mental health support platform that offers personalized care and resources in areas such as: therapy, coaching, and self-guided mindfulness exercises for all covered employees and their covered dependents.&lt;/li&gt;
&lt;/ul&gt;
&lt;p style=&quot;line-height: 1.3;&quot;&gt;&lt;em&gt;&lt;strong&gt;*&lt;/strong&gt;May vary by country and worker type - please reach out to your recruiter for more information&lt;/em&gt;&lt;/p&gt;
&lt;p style=&quot;line-height: 1.3;&quot;&gt;&lt;em&gt;Click &lt;a href=&quot;https://drive.google.com/drive/folders/1CdawUwjo1Q1B7ghZJ_owdmmHB8VtqhBu?usp=sharing&quot; target=&quot;_blank&quot;&gt;here&lt;/a&gt; to learn more about Fivetran&#39;s Benefits by Region.&lt;/em&gt;&lt;/p&gt;
&lt;hr&gt;
&lt;p style=&quot;line-height: 1.3;&quot;&gt;We’re honored to be &lt;a class=&quot;c-link&quot; href=&quot;https://fivetran.com/blog/hvr-acquisition-series-d&quot; target=&quot;_blank&quot; data-stringify-link=&quot;https://fivetran.com/blog/hvr-acquisition-series-d&quot; data-sk=&quot;tooltip_parent&quot;&gt;valued at over $5.6 billion&lt;/a&gt;, but more importantly, we’re proud of our&amp;nbsp;&lt;a class=&quot;c-link&quot; href=&quot;https://fivetran.com/culture&quot; target=&quot;_blank&quot; data-stringify-link=&quot;https://fivetran.com/culture&quot; data-sk=&quot;tooltip_parent&quot;&gt;core values of Get Stuck In, Do the Right Thing, and One Team, One Dream&lt;/a&gt;. Read about us in&amp;nbsp;&lt;a class=&quot;c-link&quot; href=&quot;https://fivetran-com.s3.amazonaws.com/news/forbes-aug-sept-2022-digital-reprint-10-21-22.pdf&quot; target=&quot;_blank&quot; data-stringify-link=&quot;https://fivetran-com.s3.amazonaws.com/news/forbes-aug-sept-2022-digital-reprint-10-21-22.pdf&quot; data-sk=&quot;tooltip_parent&quot;&gt;Forbes&lt;/a&gt;.&amp;nbsp; &amp;nbsp; &amp;nbsp;&lt;/p&gt;
&lt;p style=&quot;line-height: 1.3;&quot;&gt;Fivetran brings together high-quality talent across the globe to make data access as easy and reliable as electricity for our customers. We value and recognize that our customers benefit from having innovative teams made of people from many backgrounds, experiences, and identities. Fivetran promotes diversity, equity, inclusion &amp;amp; belonging through attracting, recruiting, developing, and retaining a diverse workforce, not only because it is the right thing to do, but because it helps us build a world-class company to better serve our customers, our people and our communities.&lt;/p&gt;
&lt;p style=&quot;line-height: 1.3;&quot;&gt;To learn more about Fivetran’s culture and what it’s like to be part of the team, &lt;a href=&quot;https://www.youtube.com/watch?v=xlhtp4dGh8o&quot; target=&quot;_blank&quot;&gt;click here&lt;/a&gt; and enjoy our video.&lt;/p&gt;
&lt;p style=&quot;line-height: 1.3;&quot;&gt;To learn more about our candidate privacy policy, you can &lt;a href=&quot;https://fivetran.com/candidate-privacy&quot; target=&quot;_blank&quot;&gt;read our statement here&lt;/a&gt;.&lt;/p&gt;
&lt;hr&gt;
&lt;p style=&quot;line-height: 1.3;&quot;&gt;&lt;em&gt;We are committed to ensuring that all candidates have an equal opportunity to participate in our interview process. If you require accommodations at any stage of the process due to a disability, medical condition, or any other circumstance, please don&#39;t hesitate to submit your request by filling out this &lt;a href=&quot;https://forms.gle/V7k3t4u9j523XkEt6&quot;&gt;form&lt;/a&gt;. We will work with you to provide reasonable accommodations to facilitate your participation and ensure a fair and accessible interview experience. Your request and any information provided will be kept confidential and will not impact your candidacy. We look forward to hearing from you and accommodating your needs to the best of our ability.&lt;/em&gt;&lt;/p&gt;&lt;/div&gt;<p>Find <a href="https://www.arbeitnow.co.uk">Jobs in United Kingdom</a> on Arbeitnow</a>

&lt;h1&gt;Senior Accountant&lt;/h1&gt;
&lt;p&gt;Location: UK, Manchester ( Hybrid)&lt;/p&gt;
&lt;h2&gt;About Inizio&lt;/h2&gt;
&lt;p&gt;Inizio is a global partner to health and life sciences organisations, delivering specialist expertise across the product and patient journey. Through Global Finance Services (GFS), we provide high-quality, efficient and compliant finance operations that support business performance worldwide.&lt;/p&gt;
&lt;h2&gt;Role Overview&lt;/h2&gt;
&lt;p&gt;Reporting to the Divisional Controller, we are seeking a Senior Accountant to lead accurate and timely period-end close activities within our Global Finance Services (GFS) shared services organisation. You will act as a subject matter expert across Record-to-Report (RTR) processes including journal preparation, balance sheet reconciliations, intercompany accounting and variance analysis while driving accounting quality, financial control and continuous improvement. Working closely with finance stakeholders, you will support governance, audit readiness and the development of junior team members.&lt;/p&gt;
&lt;h2&gt;Here&#39;s what you&#39;ll be doing&lt;/h2&gt;
&lt;h3&gt;Financial Accounting &amp;amp; Close&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;Perform and oversee complex accounting activities, reconciliations and financial reporting support processes.&lt;/li&gt;
&lt;li&gt;Own key balance sheet accounts and ensure timely reconciliation and resolution of outstanding items.&lt;/li&gt;
&lt;li&gt;Review and sign off bank reconciliations.&lt;/li&gt;
&lt;li&gt;Oversee intercompany accounting and resolution of differences.&lt;/li&gt;
&lt;li&gt;Lead assigned month-end, quarter-end and year-end close activities.&lt;/li&gt;
&lt;li&gt;Review accounting transactions and escalate issues where appropriate.&lt;/li&gt;
&lt;li&gt;Prepare and review variance analysis, providing clear commentary on movements in assigned balance sheet accounts and period-end results.&lt;/li&gt;
&lt;li&gt;Prepare and review schedules and supporting information for internal and external reporting requirements, ensuring accuracy and completeness ahead of submission deadlines.&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;Governance &amp;amp; Controls&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;Support reporting requirements, accounting policy implementation and process changes.&lt;/li&gt;
&lt;li&gt;Support internal and external audits.&lt;/li&gt;
&lt;li&gt;Identify opportunities to improve accounting processes, controls and reporting quality.&lt;/li&gt;
&lt;li&gt;Support the Divisional Controller in delivering accounting, governance and financial control objectives.&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;Leadership&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;Coach and support Accountants in the execution of accounting activities and capability development; this is not a line management responsibility but carries an expectation of technical leadership and work review.&lt;/li&gt;
&lt;/ul&gt;
&lt;h2&gt;What you&#39;ll bring&lt;/h2&gt;
&lt;h3&gt;Qualifications &amp;amp; Experience&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;Bachelor&#39;s degree (or equivalent professional qualification) in Accounting, Finance, Commerce or related discipline.&lt;/li&gt;
&lt;li&gt;Qualified ACA, ACCA, CIMA or equivalent preferred.&lt;/li&gt;
&lt;li&gt;4–8 years&#39; progressive finance experience including financial accounting, reconciliations, intercompany accounting, close activities, audit support and financial controls.&lt;/li&gt;
&lt;li&gt;Experience within a global Shared Services Centre (SSC) or Global Business Services (GBS) environment is essential.&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;Technical &amp;amp; Operational Expertise&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;ERP experience (Oracle Fusion or similar).&lt;/li&gt;
&lt;li&gt;Advanced Microsoft Excel skills.&lt;/li&gt;
&lt;li&gt;Strong accounting standards, financial reporting and balance sheet management knowledge.&lt;/li&gt;
&lt;li&gt;Knowledge of internal controls and SOX or equivalent governance.&lt;/li&gt;
&lt;li&gt;Experience supporting process improvement or automation.&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;Problem Solving &amp;amp; Innovation&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;Resolve complex reconciliations, intercompany disputes and accounting issues.&lt;/li&gt;
&lt;li&gt;Apply judgement to non-routine transactions.&lt;/li&gt;
&lt;li&gt;Drive process improvements and control enhancements.&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;Stakeholder Management &amp;amp; Communication&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;Build effective relationships with Finance, Tax, Treasury, Audit and Divisional teams.&lt;/li&gt;
&lt;li&gt;Communicate technical accounting matters clearly.&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;Performance, Impact &amp;amp; Ways of Working&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;High attention to detail and strong organisational skills.&lt;/li&gt;
&lt;li&gt;Collaborative, proactive and committed to continuous improvement.&lt;/li&gt;
&lt;/ul&gt;
&lt;h2&gt;Why join us&lt;/h2&gt;
&lt;p&gt;You&#39;ll play a key role in delivering high-quality financial reporting and strengthening accounting controls across Global Finance Services while supporting continuous improvement and operational excellence.&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;#LI-DT2 #LI-HYBRID&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;div class=&quot;elementToProof&quot;&gt;&lt;em&gt;Don&#39;t meet every job requirement? That&#39;s okay! Our company is dedicated to building an inclusive and authentic workplace. If you&#39;re excited about this role, but your experience doesn&#39;t perfectly fit every qualification, we encourage you to apply anyway. You may be just the right person for this role or others.&lt;/em&gt;&lt;/div&gt;&lt;/div&gt;<p>Find more <a href="https://www.arbeitnow.co.uk/english-speaking-jobs">English Speaking Jobs in United Kingdom</a> on Arbeitnow</a>

&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;&lt;strong&gt;Who we are&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;At Twilio, we’re shaping the future of communications, all from the comfort of our homes. We deliver innovative solutions to&lt;a class=&quot;c-link&quot; href=&quot;https://customers.twilio.com/&quot; target=&quot;_blank&quot; data-stringify-link=&quot;https://customers.twilio.com/&quot; data-sk=&quot;tooltip_parent&quot;&gt;&amp;nbsp;hundreds of thousands of businesses&amp;nbsp;&lt;/a&gt;and empower millions of developers worldwide to craft personalized customer experiences.&lt;/p&gt;
&lt;p&gt;Our dedication to &lt;a class=&quot;c-link&quot; href=&quot;https://www.twilio.com/en-us/blog/open-work&quot; target=&quot;_blank&quot; data-stringify-link=&quot;https://www.twilio.com/en-us/blog/open-work&quot; data-sk=&quot;tooltip_parent&quot;&gt;remote-first work&lt;/a&gt;, and strong culture of connection and global inclusion means that no matter your location, you’re part of a vibrant team with diverse experiences making a global impact each day. As we continue to revolutionize how the world interacts, we’re acquiring new skills and experiences that make work feel truly rewarding. Your career at Twilio is in your hands.&lt;br&gt;&lt;span style=&quot;color: rgb(255, 255, 255);&quot;&gt;.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Hiring and how we work&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;We use Artificial Intelligence (AI) to help make our hiring process efficient. That said, every hiring decision is made by real Twilions!&amp;nbsp;&lt;/p&gt;
&lt;p&gt;Also, while we are a remote-first company, you may be asked to report in person on an ad-hoc basis for team gatherings, functional off-sites or customer meetings.&amp;nbsp;&lt;br&gt;&lt;span style=&quot;color: rgb(255, 255, 255);&quot;&gt;.&lt;/span&gt;&lt;/p&gt;&lt;/div&gt;&lt;p&gt;&lt;strong&gt;See yourself at Twilio&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Join the team as Twilio’s next Director of Global Campaigns.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;About the job&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;As the head of the Twilio Global Campaign team, you are responsible for owning, developing and executing the major campaigns that drive awareness and opportunities for Twilio. This role is highly cross functional, working closely with both internal marketing partners across regions, sales, product, and company leadership to design end-to-end campaigns that deliver on business objectives. You possess a proven track record of leading multi-channel global campaigns with success, collaborating with stakeholders, and finding opportunities to strategically uplevel Twilio’s campaign engine.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;The ideal candidate has an advanced understanding of how campaigns resonate with a global audience, not just one country. You are skilled in understanding the modern AI-driven buyer journey at each stage of the funnel, have the ability to translate messaging frameworks into effective campaigns, and thrives in a collaborative environment. You recognize the value of running an integrated campaign motion, and have the ability to think both strategically and execute at an operational level with ease. Your performance will be measured by your ability to execute and achieve measurable results including building brand awareness, developing a system of content and assets that is valuable to all regions, and building campaigns that accelerate growth velocity.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;br&gt;&lt;strong&gt;Responsibilities&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;In this role, you will:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;Set a strategic vision&lt;/strong&gt; for global campaign structure, operations, and execution for our top 5 campaign motions. We are looking for someone who is very strategic in terms of knowing the audience, how to create content that resonates, tactics to reach that audience, and ideas that are visionary and tactical.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Be accountable&lt;/strong&gt; to company leadership on the effectiveness of all global campaigns and programs&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Strong project management skills&lt;/strong&gt; and ability to use data to guide decision-making and resource allocation. Design and execute strategic end-to-end campaigns that both engage and convert prospective buyers with a focus on specific buyer and vertical segments&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Partner&lt;/strong&gt; with product marketing, content strategists, brand strategists, creative designers and other regional campaign teams to create campaign themes and messaging that translate into impactful marketing campaigns. Act as the central point of contact to direct all campaign work across teams to ensure timely results&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Build strong relationships&lt;/strong&gt; with key cross functional stakeholders across multiple organizations to ensure campaign enablement and engagement&amp;nbsp;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;A global systems approach. &lt;/strong&gt;Develop scalable, repeatable campaign playbooks that can be scaled quickly with a large variety of content that works in all regions&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Track program results&lt;/strong&gt;, measure program success and report metrics to customer success, sales and marketing stakeholders and executives. Then analyze campaign performance, surface insights and provide recommendations for optimizing results&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;AI-Driven Enablement:&lt;/strong&gt; We want you to infuse AI frameworks into all aspects of the campaign model. Ideally you would disrupt the norms and evolve the team and programs to be progressive. And equip teams across the organization with the tools, guidelines, and frameworks to create high-quality content at scale, including standards, reusable templates, and AI-assisted workflows that improve consistency, speed, and quality.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Budget Management:&lt;/strong&gt; Manage and allocate budget for campaign production resources across all campaign and persona needs, including original content, video production, localization, and agencies to ensure efficient and high-quality execution and return on investment&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Global team leadership: &lt;/strong&gt;Manage a team with a global remit that spans all regions from the US to Europe to Asia, while working with company and brand leadership to execute all top-of-funnel campaigns.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Qualifications&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Twilio values diverse experiences from all kinds of industries, and we encourage everyone who meets the required qualifications to apply. If your career is just starting or hasn&#39;t followed a traditional path, don&#39;t let that stop you from considering Twilio. We are always looking for people who will bring something new to the table!&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Required:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Management experience: ability to inspire a team of strategists and show a vision of what is possible and where our teams should focus efforts&lt;/li&gt;
&lt;li&gt;Deep understanding of marketing funnel tactics and metrics by stage, PLG model and funnel&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Understanding of enterprise buying cycles, sales processes and stakeholders, especially in B2B tech&lt;/li&gt;
&lt;li&gt;Self-starter who excels in a fast-paced, collaborative, and innovative high-growth environment&lt;/li&gt;
&lt;li&gt;Ability to manage multiple work streams and has presence with the team and leadership&lt;/li&gt;
&lt;li&gt;Strategic thinker with strong attention to detail&lt;/li&gt;
&lt;li&gt;8+ years working as a campagin strategist in B2B or tech&lt;/li&gt;
&lt;li&gt;Proven experience building and delivering on integrated programs and managing all tools, processes, and assets&lt;/li&gt;
&lt;li&gt;Exceptional communication skills, both verbal and written, with the ability to drive alignment, set expectations and drive to success&lt;/li&gt;
&lt;li&gt;Works well with cross-functional teams and executives, to ensure consistent content is delivered across the company&lt;/li&gt;
&lt;li&gt;A champion for fostering a culture of trust through feedback, communication, and transparency&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Desired:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Excellent written and verbal communication skills.&lt;/li&gt;
&lt;li&gt;Ability to influence and build effective working relationships with all levels of the organization.&lt;/li&gt;
&lt;li&gt;Familiarity with localization tactics to ensure our content is accessible and inclusive across multiple countries.&lt;/li&gt;
&lt;li&gt;Experience with primary research strategies and types of content creation&lt;/li&gt;
&lt;li&gt;Strategic ability to see opportunities across campaigns and programs where new types of content and programs will thrive.&lt;/li&gt;
&lt;li&gt;Experience building world-class brands through premium content&lt;/li&gt;
&lt;li&gt;Experience with a variety of AI, design, analytics, and video tools. Proficiency in digital marketing tools and platforms such as Tableau, Salesforce, AEM, Google Analytics, LinkedIn Campaign Manager, Meta Ads Manager, Canva&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Location&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;This role will be remote based in Ireland or the UK&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Travel&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;We prioritize connection and opportunities to build relationships with our customers and each other. For this role, you may be required to travel occasionally to participate in project or team in-person meetings.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;What We Offer&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Working at Twilio offers many benefits, including competitive pay, generous time off, ample parental and wellness leave, healthcare, a retirement savings program, and much more. Offerings vary by location.&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;&lt;strong&gt;Twilio thinks big. Do you?&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;We like to solve problems, take initiative, pitch in when needed, and are always up for trying new things. That&#39;s why we seek out colleagues who embody our values — something we call &lt;a href=&quot;https://www.twilio.com/company/values&quot;&gt;Twilio Magic&lt;/a&gt;. Additionally, we empower employees to build &lt;a href=&quot;https://twilio.org/support-and-resources/impact-fund&quot;&gt;positive change in their communities&lt;/a&gt; by supporting their volunteering and donation efforts.&lt;/p&gt;
&lt;p&gt;So, if you&#39;re ready to unleash your full potential, do your best work, and be the best version of yourself, apply now! If this role isn&#39;t what you&#39;re looking for, &lt;a href=&quot;https://www.twilio.com/company/jobs#open-positions&quot;&gt;please consider other open positions.&lt;/a&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span style=&quot;color: rgb(255, 255, 255);&quot;&gt;.&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Stay alert to recruitment fraud&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;We care about your safety. Scammers sometimes impersonate Twilio recruiters through fake job postings, emails, websites, or messages. Please ensure you are engaging with an official @&lt;a href=&quot;http://twilio.com&quot;&gt;twilio.com&lt;/a&gt; email address. We will never ask for payment, gift cards, cryptocurrency, or banking information during the recruiting process. We do not make job offers without a formal interview process or conduct interviews exclusively through text-based messaging apps.&lt;br&gt;&lt;br&gt;&lt;span style=&quot;color: rgb(255, 255, 255);&quot;&gt;.&lt;/span&gt;&lt;strong&gt; &lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Twilio is proud to be an equal opportunity employer.&lt;/strong&gt; We do not discriminate based upon race, religion, color, national origin, sex (including pregnancy, childbirth, reproductive health decisions, or related medical conditions), sexual orientation, gender identity, gender expression, age, status as a protected veteran, status as an individual with a disability, genetic information, political views or activity, or other applicable legally protected characteristics. We also consider qualified applicants with criminal histories, consistent with applicable federal, state and local law. Qualified applicants with arrest or conviction records will be considered for employment in accordance with the Los Angeles County Fair Chance Ordinance for Employers and the California Fair Chance Act. Additionally, Twilio participates in the E-Verify program in certain locations, as required by law.&lt;/p&gt;&lt;/div&gt;<p>Find more <a href="https://www.arbeitnow.co.uk/english-speaking-jobs">English Speaking Jobs in United Kingdom</a> on Arbeitnow</a>

&lt;p&gt;&lt;strong&gt;&lt;span lang=&quot;EN-US&quot;&gt;Mission Brief&amp;nbsp;&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;div&gt;We are looking for a Senior Group Accountant to come on board and own the monthly consolidation process, as well as take responsibility for the entire Group Accounting function.&amp;nbsp;&lt;/div&gt;
&lt;div&gt;
&lt;div&gt;The scope of this role will evolve over time, making it an excellent opportunity for someone who enjoys taking on new challenges.&lt;/div&gt;
&lt;/div&gt;
&lt;p&gt;&lt;strong&gt;&lt;span class=&quot;TextRun SCXW114497174 BCX8&quot; lang=&quot;EN-US&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun CommentStart CommentHighlightPipeRest CommentHighlightRest SCXW114497174 BCX8&quot;&gt;Your Role in Our Space Mission:&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;div&gt;
&lt;ul&gt;
&lt;li&gt;Responsible for the monthly, quarterly, and year-end consolidation of the Group Financial Statements under IFRS and HGB.&lt;/li&gt;
&lt;li&gt;Oversee the Group transfer pricing agreements.&lt;/li&gt;
&lt;li&gt;Maintain intercompany relationships within the Group.&lt;/li&gt;
&lt;li&gt;Support both Group and local audits, as well as liaise with local auditors.&lt;/li&gt;
&lt;li&gt;Provide functional support for SAP FI/CO and contribute to system enhancements (ideally SAP S/4HANA).&lt;/li&gt;
&lt;li&gt;Participate in projects such as M&amp;amp;A, post-merger integration, and system migrations.&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;p&gt;&lt;strong&gt;&lt;span lang=&quot;EN-US&quot;&gt;&lt;span class=&quot;EOP CommentHighlightPipeRest SCXW114497174 BCX8&quot; data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559740&amp;quot;:360}&quot;&gt;Qualification Checklist&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;div&gt;Qualified Accountant (ACCA, ACA, CPA) is desirable.&lt;/div&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;div&gt;Over 10 years of relevant professional experience.&lt;/div&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;div&gt;Strong knowledge of SAP FI/CO, ideally SAP S/4HANA.&lt;/div&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;div&gt;Experience with Lucanet or an equivalent consolidation tool.&lt;/div&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;div&gt;Fluent in English; German is a plus.&lt;/div&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;div&gt;Deep expertise in IFRS; knowledge of HGB is a plus.&lt;/div&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;div&gt;Extensive experience in Group Accounting and consolidations.&lt;/div&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;div&gt;High degree of independence and professionalism in a staff function.&lt;/div&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;Bonus Skills&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Experience in US, Canadian or Scandinavian GAAP&lt;/li&gt;
&lt;li&gt;Experience with ERP migrations&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;&lt;span lang=&quot;EN-US&quot;&gt;Benefits&amp;nbsp;&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;Employee Participation Program: &lt;/strong&gt;Share in our success through our virtual company share program&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;30 days of vacation: &lt;/strong&gt;Enjoy the days off to relax and recharge&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Company pension plan:&lt;/strong&gt; Secure your future with our company pension plan, featuring a 20% employer contribution after the probation period&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Subsidised lunch:&lt;/strong&gt; Stay energised with delicious, subsidised lunches every day&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Public transport ticket: &lt;/strong&gt;Commute with ease using a fully financed Deutschlandticket&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Sport Clubs membership: &lt;/strong&gt;Stay fit with our sponsored sports club memberships (EGYM Wellpass)&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Individual learning allowance:&lt;/strong&gt; Grow your skills with an individual learning budget granted after the probation period&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Childcare allowance:&lt;/strong&gt; Receive a childcare allowance for your non-school-age children&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;And Much More!&lt;/strong&gt; Discover additional perks and benefits when you join our team&amp;nbsp; &amp;nbsp; &amp;nbsp; &amp;nbsp;&amp;nbsp;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;&lt;span lang=&quot;EN-US&quot;&gt;Who we are&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span lang=&quot;EN-US&quot;&gt;&lt;iframe src=&quot;https://www.youtube.com/embed/jW2V5vsMb_k&quot; width=&quot;560&quot; height=&quot;314&quot;&gt;&lt;/iframe&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;span lang=&quot;EN-US&quot;&gt;We are Isar Aerospace and we are at the forefront of New Space building a modern space business to enable faster, better and cheaper access to space.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span lang=&quot;EN-US&quot;&gt;Our mission is to help democratise space and use it for good in order to improve life on Earth now and for the future generations.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span lang=&quot;EN-US&quot;&gt;We are a fast-growing company aiming to provide sustainable and environmentally friendly launch solutions for small and medium-sized satellites and constellations into Low Earth Orbit. The company is privately funded by world-leading technology investors with strong commitment and support and our team is made of driven and talented people with a real passion for space innovation.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span lang=&quot;EN-US&quot;&gt;We&#39;re making rockets in a way that hasn&#39;t been done before disrupting a traditional industry. If you are up for the challenge, want to work on cutting-edge projects and be part of a team changing the world for better, come, join us and launch your career!&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span lang=&quot;EN-US&quot;&gt;Want to find out more about us?&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span lang=&quot;EN-US&quot;&gt;Visit &lt;/span&gt;&lt;span lang=&quot;DE&quot;&gt;&lt;a href=&quot;http://www.isaraerospace.com/&quot;&gt;www.isaraerospace.com&lt;/a&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span lang=&quot;DE&quot;&gt;&lt;strong&gt;Data Protection&lt;br&gt;&lt;/strong&gt;We process your personal data for the purpose of managing the recruitment process and assessing your application. For detailed information on how your data is processed, including your rights, please refer to our &lt;a id=&quot;menur31jp&quot; class=&quot;fui-Link ___1q1shib f2hkw1w f3rmtva f1ewtqcl fyind8e f1k6fduh f1w7gpdv fk6fouc fjoy568 figsok6 f1s184ao f1mk8lai fnbmjn9 f1o700av f13mvf36 f1cmlufx f9n3di6 f1ids18y f1tx3yz7 f1deo86v f1eh06m1 f1iescvh fhgqx19 f1olyrje f1p93eir f1nev41a f1h8hb77 f1lqvz6u f10aw75t fsle3fq f17ae5zn&quot; href=&quot;https://isaraerospace.com/privacy-policy&quot; target=&quot;_blank&quot;&gt;Privacy Policy&lt;/a&gt;.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span lang=&quot;DE&quot;&gt;Disclaimer&lt;br&gt;&lt;/span&gt;&lt;/strong&gt;&lt;span lang=&quot;DE&quot;&gt;&lt;span lang=&quot;EN-US&quot;&gt;Isar Aerospace SE is an equal-opportunity employer committed to fairness and inclusivity. We do not prioritize any specific religion, gender, nationality, or background. Due to security clearance requirements, affiliations with countries listed under § 13 para. 1 no. 17 SÜG may affect the application process. All qualified applicants are encouraged to apply.&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span lang=&quot;DE&quot;&gt;&lt;span lang=&quot;EN-US&quot;&gt;&lt;strong&gt;Metaview&lt;/strong&gt;&lt;br&gt;&lt;span data-teams=&quot;true&quot;&gt;We use Metaview to record interview audio so our team can review it later and stay focused during the conversation. We will record interviews only if you opt in. Please note that we will request your consent separately during the interview process. Participation is completely voluntary and will not affect your application in any way. For more information on how we process your personal data, please see our&amp;nbsp;&lt;a id=&quot;menur2eic&quot; class=&quot;fui-Link ___1q1shib f2hkw1w f3rmtva f1ewtqcl fyind8e f1k6fduh f1w7gpdv fk6fouc fjoy568 figsok6 f1s184ao f1mk8lai fnbmjn9 f1o700av f13mvf36 f1cmlufx f9n3di6 f1ids18y f1tx3yz7 f1deo86v f1eh06m1 f1iescvh fhgqx19 f1olyrje f1p93eir f1nev41a f1h8hb77 f1lqvz6u f10aw75t fsle3fq f17ae5zn&quot; href=&quot;https://deu01.safelinks.protection.outlook.com/?url=https%3A%2F%2Fisaraerospace.com%2Fprivacy-policy&amp;amp;data=05%7C02%7Cbritta.bonn%40ext.isaraerospace.com%7Cbf5a1173fd434834ab1c08dea5c061eb%7C50154d7ed4fe4770bb43bf09a927cc45%7C0%7C0%7C639130442882001477%7CUnknown%7CTWFpbGZsb3d8eyJFbXB0eU1hcGkiOnRydWUsIlYiOiIwLjAuMDAwMCIsIlAiOiJXaW4zMiIsIkFOIjoiTWFpbCIsIldUIjoyfQ%3D%3D%7C0%7C%7C%7C&amp;amp;sdata=l1vw27o02fEuCFAICyAHO91ObS%2FjnXDl5woYeGiSRek%3D&amp;amp;reserved=0&quot; target=&quot;_blank&quot;&gt;Privacy Policy&lt;/a&gt;.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;<p>Find more <a href="https://www.arbeitnow.com/english-speaking-jobs">English Speaking Jobs in Germany</a> on Arbeitnow</a>

&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;At Alpine Eagle,&amp;nbsp;we’re&amp;nbsp;building the future of counter-drone&amp;nbsp;defence.&amp;nbsp;We’re&amp;nbsp;a fast-growing, international deep-tech company working at the intersection of aerospace engineering,&amp;nbsp;defence&amp;nbsp;systems, and machine learning. Our goal: create the world’s first swarm-based, airborne counter-drone system.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Modern conflicts show how quickly drones are reshaping the battlefield. Threats are rising, and today’s solutions&amp;nbsp;aren’t&amp;nbsp;keeping pace.&amp;nbsp;We’re&amp;nbsp;here to change that.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Alpine Eagle&amp;nbsp;isn’t&amp;nbsp;just a&amp;nbsp;defence&amp;nbsp;company.&amp;nbsp;It’s&amp;nbsp;a mission. Backed by an international team, strong funding, and a bold vision,&amp;nbsp;we’re&amp;nbsp;looking for people who want to shape the next generation of aerial security and build something that truly matters.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;We are looking for a&amp;nbsp;&lt;/span&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Full Stack Engineer with a strong frontend focus and a proven background in human-machine interfaces for complex operational systems&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;. You will turn complex sensor, agent, and mission data into an intuitive operational picture and effective control interfaces.&lt;/span&gt; &amp;nbsp;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;🎯&lt;/strong&gt;&lt;strong&gt; How you will make an impact:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;15&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559683&amp;quot;:0,&amp;quot;335559684&amp;quot;:-2,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Develop high-performance frontend applications using&amp;nbsp;&lt;/span&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;TypeScript and React&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;15&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559683&amp;quot;:0,&amp;quot;335559684&amp;quot;:-2,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;2&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Take ownership of&amp;nbsp;&lt;/span&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;frontend architecture&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;and&amp;nbsp;establish&amp;nbsp;reusable patterns for complex visualization and operator workflows&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;15&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559683&amp;quot;:0,&amp;quot;335559684&amp;quot;:-2,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;3&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Develop intuitive and ergonomic operator workflows for&amp;nbsp;&lt;/span&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;real-time, information-dense environments&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;15&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559683&amp;quot;:0,&amp;quot;335559684&amp;quot;:-2,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;4&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Build interfaces for monitoring&amp;nbsp;&lt;/span&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;system state, sensor information, agent activities, effector status, tracks, and mission data&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;15&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559683&amp;quot;:0,&amp;quot;335559684&amp;quot;:-2,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;5&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Develop interactive&amp;nbsp;&lt;/span&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;maps, GIS-based interfaces, and 2D/3D visualizations&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
