&lt;blockquote&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;text-start&quot; data-ccp-parastyle-defn=&quot;{&amp;quot;ObjectId&amp;quot;:&amp;quot;8196cb6b-cd51-5eab-845a-560d08e94671|1&amp;quot;,&amp;quot;ClassId&amp;quot;:1073872969,&amp;quot;Properties&amp;quot;:[335551547,&amp;quot;1033&amp;quot;,201342447,&amp;quot;5&amp;quot;,201342448,&amp;quot;1&amp;quot;,469777841,&amp;quot;Times New Roman&amp;quot;,469777842,&amp;quot;Times New Roman&amp;quot;,469777843,&amp;quot;Times New Roman&amp;quot;,469777844,&amp;quot;Times New Roman&amp;quot;,469769226,&amp;quot;Times New Roman&amp;quot;,335551500,&amp;quot;4278190080&amp;quot;,268442635,&amp;quot;24&amp;quot;,469775450,&amp;quot;text-start&amp;quot;,201340122,&amp;quot;2&amp;quot;,134233614,&amp;quot;true&amp;quot;,469778129,&amp;quot;text-start&amp;quot;,335572020,&amp;quot;1&amp;quot;,335559740,&amp;quot;240&amp;quot;,201341983,&amp;quot;0&amp;quot;,134233118,&amp;quot;true&amp;quot;,134233117,&amp;quot;true&amp;quot;,469778324,&amp;quot;Normal&amp;quot;]}&quot;&gt;&lt;em&gt;Helping organizations turn software ambition into decisions they can stand behind&amp;nbsp;&lt;/em&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;text-start&quot; data-ccp-parastyle-defn=&quot;{&amp;quot;ObjectId&amp;quot;:&amp;quot;8196cb6b-cd51-5eab-845a-560d08e94671|1&amp;quot;,&amp;quot;ClassId&amp;quot;:1073872969,&amp;quot;Properties&amp;quot;:[335551547,&amp;quot;1033&amp;quot;,201342447,&amp;quot;5&amp;quot;,201342448,&amp;quot;1&amp;quot;,469777841,&amp;quot;Times New Roman&amp;quot;,469777842,&amp;quot;Times New Roman&amp;quot;,469777843,&amp;quot;Times New Roman&amp;quot;,469777844,&amp;quot;Times New Roman&amp;quot;,469769226,&amp;quot;Times New Roman&amp;quot;,335551500,&amp;quot;4278190080&amp;quot;,268442635,&amp;quot;24&amp;quot;,469775450,&amp;quot;text-start&amp;quot;,201340122,&amp;quot;2&amp;quot;,134233614,&amp;quot;true&amp;quot;,469778129,&amp;quot;text-start&amp;quot;,335572020,&amp;quot;1&amp;quot;,335559740,&amp;quot;240&amp;quot;,201341983,&amp;quot;0&amp;quot;,134233118,&amp;quot;true&amp;quot;,134233117,&amp;quot;true&amp;quot;,469778324,&amp;quot;Normal&amp;quot;]}&quot;&gt;The &lt;/span&gt;&lt;/span&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;text-start&quot;&gt;Commercial Software Lead&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;text-start&quot;&gt;&amp;nbsp;at Schuberg Philis is a commercially driven technologist who bridges proposition strategy and customer execution. Embedded in Greater Customer Teams (GCTs), the Commercial Software Lead translates customer challenges into compelling, standardized software solutions, accelerates sales cycles through technical&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;text-start&quot;&gt;expertise&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;text-start&quot;&gt;, and ensures that what we propose is both desirable for customers and&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;text-start&quot;&gt;feasible&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;text-start&quot;&gt;&amp;nbsp;for our delivery teams. Working closely with&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;text-start&quot;&gt;Sales Directors and the Software&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;text-start&quot;&gt;Ambassador, the Commercial Software Lead is the expert in the room—driving adoption of our&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;text-start&quot;&gt;Software&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;text-start&quot;&gt;proposition&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;text-start&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;text-start&quot;&gt;and turning market-leading software services into signed contracts and successful customer outcomes.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;text-start&quot;&gt;Your&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;text-start&quot;&gt;&amp;nbsp;impact&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
